		inner.setProjectionContext(Var.of("callerGraph"));
		inner.setInheritedGraphParameter("privateGraph");
		StatementPattern pattern = patterns.getFirst();
		StatementPattern namedPattern = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS,
				pattern.getSubjectVar().clone(), pattern.getPredicateVar().clone(), pattern.getObjectVar().clone(),
				Var.of("privateGraph"));
		namedPattern.setVariableScopeChange(pattern.isVariableScopeChange());
		namedPattern.setIndependentInputScope(pattern.isIndependentInputScope());
		namedPattern.setContextBindingOriginInherited(true);
		pattern.replaceWith(namedPattern);
